def frames(lines):
    results = []
    buffer = []
    for line in lines:
        if line == "":
            if buffer:
                results.append("\n".join(buffer))
            buffer = []
        elif line.startswith(":"):
            pass
        else:
            if ":" in line:
                field, _, value = line.partition(":")
            else:
                field, value = line, ""
            if field == "data":
                if value.startswith(" "):
                    value = value[1:]
                buffer.append(value)
    return results
