def unique_latest(records):
    best = {}
    order = []
    for rec in records:
        rid = rec['id']
        if rid not in best:
            order.append(rid)
            best[rid] = rec
        elif rec['timestamp'] >= best[rid]['timestamp']:
            best[rid] = rec
    return [best[rid] for rid in order]
