from bisect import bisect_right


def histogram(edges, values):
    if not hasattr(edges, '__len__') or len(edges) < 2:
        raise ValueError("edges must be a list with at least two numbers")
    for i in range(len(edges) - 1):
        if not edges[i] < edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    n = len(edges)
    counts = [0] * (n - 1)

    for v in values:
        idx = bisect_right(edges, v)
        if idx == 0:
            continue
        if idx == n:
            if v == edges[-1]:
                counts[-1] += 1
            continue
        counts[idx - 1] += 1

    return counts
```

