import copy


def merge(base, overlay):
    """Recursively merge two dictionaries into a deep-independent result.

    - Overlay values replace base values (including lists and None).
    - A None value does not delete a key; it simply sets it to None.
    - Both inputs remain unmutated and unaliased in the result.
    """
    result = {}

    for key in base:
        if key in overlay:
            b_val = base[key]
            o_val = overlay[key]
            if isinstance(b_val, dict) and isinstance(o_val, dict):
                result[key] = merge(b_val, o_val)
            else:
                result[key] = copy.deepcopy(o_val)
        else:
            result[key] = copy.deepcopy(base[key])

    for key in overlay:
        if key not in base:
            result[key] = copy.deepcopy(overlay[key])

    return result
