def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")
    if not items:
        return []

    result = []
    batch = []
    current = 0

    for item in items:
        n = len(item.encode("utf-8"))
        if n > max_bytes:
            raise ValueError(f"item {item!r} does not fit in max_bytes={max_bytes}")
        if current + n > max_bytes:
            result.append(batch)
            batch = []
            current = 0
        batch.append(item)
        current += n

    if batch:
        result.append(batch)

    return result
