from collections import deque

def admit(times, limit, window):
    if limit < 1 or window < 1:
        raise ValueError
    dq = deque()
    result = []
    for t in times:
        while dq and dq[0] <= t - window:
            dq.popleft()
        if len(dq) < limit:
            result.append(True)
            dq.append(t)
        else:
            result.append(False)
    return result
