import heapq


def order(deps):
    # Collect all nodes (keys + prerequisite-only nodes)
    all_nodes = set(deps.keys())
    for prereqs in deps.values():
        for p in prereqs:
            all_nodes.add(p)

    # Build deduplicated prerequisite sets and reverse adjacency
    in_degree = {node: 0 for node in all_nodes}
    dependents = {node: set() for node in all_nodes}

    for node in all_nodes:
        for p in set(deps.get(node, [])):
            dependents[p].add(node)
            in_degree[node] += 1

    # Min-heap of currently ready nodes (all prerequisites satisfied)
    heap = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dep in dependents[node]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result
```

