def redact(value, sensitive):
    sensitive_set = {s.lower() for s in sensitive}
    if isinstance(value, dict):
        result = {}
        for k, v in value.items():
            if k.lower() in sensitive_set:
                result[k] = "[REDACTED]"
            else:
                result[k] = redact(v, sensitive)
        return result
    elif isinstance(value, list):
        return [redact(item, sensitive) for item in value]
    else:
        return value
